"""Server-owned mission checks. Correct option IDs are never sent with lesson metadata."""
def q(id,prompt,options,correct,feedback):
 return {'id':id,'prompt':prompt,'options':[{'id':str(i),'label':v} for i,v in enumerate(options)],'correct':str(correct),'feedback':feedback}
