def mission_for(lesson):
 questions=BANK.get(lesson['id'],[])
 return {'title':lesson['title']+' · миссия','prompt':'Кампус тапсырмасын орында: әр жағдайда дұрыс шешімді таңда. Қателессең, кеңесті оқып қайта сына.','questions':[{k:v for k,v in x.items() if k not in ('correct','feedback')} for x in questions]}
def grade(lesson_id,answers):
 questions=BANK.get(lesson_id,[])
 if not isinstance(answers,dict) or not questions:return False,[]
 criteria=[{'id':x['id'],'passed':answers.get(x['id'])==x['correct'],'feedback':('Дұрыс. ' if answers.get(x['id'])==x['correct'] else 'Қайта қара: ')+x['feedback']} for x in questions]
 return all(x['passed'] for x in criteria),criteria
